// ai-excited-04 — "The Sun Opens Its Eye"
// Writes the entry image deterministically to /output/entry.png.
// Node 22+, stdlib only. The image bytes are embedded below (base64 PNG,
// generated fresh for this entry with Python PIL — see generate_image.py).
// Running this program twice produces byte-identical output.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PNG_BASE64 = "";

const outDir = "/output";
mkdirSync(outDir, { recursive: true });
const outPath = join(outDir, "entry.png");
writeFileSync(outPath, Buffer.from(PNG_BASE64, "base64"));
console.log(`wrote ${outPath}`);
